def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_sum = 0
        has_numeric = False
        for r in rows:
            cell = r[i]
            if isinstance(cell, (int, float)):
                col_sum += cell
                has_numeric = True
        if has_numeric:
            totals.append(col_sum)
        else:
            totals.append("")
    return totals

